using System;

namespace Realmkeeper.Domain.Identifiers
{
    /// <summary>
    /// Stable, GUID-based identifier. Never derived from display names.
    /// Generated by <see cref="Realmkeeper.Domain.Randomness.DeterministicGuid"/> during
    /// world generation/simulation so identical seeds reproduce identical identifiers.
    /// </summary>
    public readonly struct TradeRouteId : IEquatable<TradeRouteId>, IComparable<TradeRouteId>
    {
        public Guid Value { get; }

        public TradeRouteId(Guid value)
        {
            Value = value;
        }

        public static TradeRouteId Empty => default;

        public bool IsEmpty => Value == Guid.Empty;

        /// <summary>Creates a random (non-deterministic) identifier. Use only outside simulation/generation.</summary>
        public static TradeRouteId NewRandom() => new TradeRouteId(Guid.NewGuid());

        public static TradeRouteId Parse(string text) => new TradeRouteId(Guid.Parse(text));

        public static bool TryParse(string text, out TradeRouteId id)
        {
            if (Guid.TryParse(text, out var guid))
            {
                id = new TradeRouteId(guid);
                return true;
            }

            id = Empty;
            return false;
        }

        public bool Equals(TradeRouteId other) => Value.Equals(other.Value);

        public override bool Equals(object obj) => obj is TradeRouteId other && Equals(other);

        public override int GetHashCode() => Value.GetHashCode();

        public int CompareTo(TradeRouteId other) => Value.CompareTo(other.Value);

        public override string ToString() => Value.ToString("D");

        public static bool operator ==(TradeRouteId left, TradeRouteId right) => left.Equals(right);

        public static bool operator !=(TradeRouteId left, TradeRouteId right) => !left.Equals(right);
    }
}
